# Serial port reader for a Raspberry Pi talking to a connected device
# Uses pyserial to exchange data over the UART and prints each reading
# Includes a simple validity check so the Pi can reject bad input
import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600


def read_serial_line(serial_connection, timeout_seconds=1):
    """Read one line from the serial port, stripping whitespace."""
    # Read all available bytes and decode them into text
    raw_bytes = serial_connection.readline()
    if not raw_bytes:
        return None
    return raw_bytes.decode("utf-8", errors="ignore").strip()


def process_reading(raw_reading):
    """Check a reading is numeric before treating it as a number."""
    # Reject any line that cannot be converted to a float
    try:
        reading_value = float(raw_reading)
        return reading_value
    except ValueError:
        return None


def main():
    """Open the serial port and print valid readings from the device."""
    serial_connection = None
    try:
        # Open the serial port and set a reasonable timeout
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print("Listening on serial port", SERIAL_PORT)
        while True:
            raw_reading = read_serial_line(serial_connection)
            if raw_reading is None:
                print("No reading received")
                break
            valid_reading = process_reading(raw_reading)
            if valid_reading is not None:
                print("Device reading:", valid_reading)
            else:
                print("Skipping invalid reading:", raw_reading)
            time.sleep(0.1)
    except serial.SerialException as serial_error:
        # Report any failure to open or communicate over the port
        print("Serial error:", serial_error)
    finally:
        # Always close the serial port when finished
        if serial_connection is not None:
            serial_connection.close()
            print("Serial port closed")


if __name__ == "__main__":
    main()

