# adc_monitor.py
# Monitors an MCP3008 ADC channel and prints readings.
# Requires: adafruit-circuitpython-mcp3xxx

import time
import sys
from board import SCL, SDA
from busio import I2C
from adafruit_mcp3xxx import ADC

# Constants
NUM_READINGS = 3
DELAY_SECONDS = 60

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return I2C(0, SCL=SCL, SDA=SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the MCP3008 ADC."""
    try:
        return ADC(i2c_bus, channel=0)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def read_adc_channel(adc_device, channel=0):
    """Reads the voltage from the specified ADC channel."""
    try:
        return adc_device.value
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

def validate_reading(reading):
    """Validates the ADC reading (optional)."""
    if reading is None:
        return False
    return True

def format_output(channel, reading, valid):
    """Formats the output string."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S %Z")
    output = f"{timestamp} ADC Channel {channel}: "
    if valid:
        output += f"{reading:.3f} V\n"
    else:
        output += "INVALID\n"
    return output

def main():
    """Main function to monitor the ADC."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        sys.exit(1)

    try:
        for reading_index in range(NUM_READINGS):
            reading = read_adc_channel(adc_device)
            is_valid = validate_reading(reading)
            print(format_output(0, reading, is_valid))
            time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nMonitoring interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No need to explicitly close the I2C bus or ADC object
        # They are automatically garbage collected when the program exits.
        print("Exiting ADC monitor.")

if __name__ == "__main__":
    main()

