# gpio_triple_digital_server.py
# Control three digital outputs on a Raspberry Pi for a distributed system.
# Hardware: Raspberry Pi 3 B+, 3x 10kΩ pull-down resistors, 3x LEDs.
# GPIO pins: 2, 5, 17 (BCM numbering).

import time
from gpiozero import DigitalOutputDevice

# Define the GPIO pins for the digital outputs.
LED_PINS = [2, 5, 17]

# Create DigitalOutputDevice objects for each pin.
led_devices = []
for pin_number in LED_PINS:
    device = DigitalOutputDevice(pin_number)
    led_devices.append(device)


def set_output(pin_index, state):
    """Set the state of a single output pin."""
    try:
        led_devices[pin_index].on() if state else led_devices[pin_index].off()
    except IndexError:
        print(f"Invalid pin index: {pin_index}")


def report_state():
    """Print the current state of all three outputs."""
    print("State of outputs:")
    for index, device in enumerate(led_devices):
        print(f"Pin {index}: {'ON' if device.value else 'OFF'}")


if __name__ == "__main__":
    try:
        # Main loop to toggle the outputs.
        while True:
            report_state()
            for index, device in enumerate(led_devices):
                set_output(index, not device.value)
            time.sleep(0.1)

    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully.
        print("\nExiting program.")

    finally:
        # Ensure all outputs are off and resources are released.
        for device in led_devices:
            device.off()
        print("Outputs set to OFF. GPIO resources released.")

