    """Initializes the I2C bus."""
    try:
        bus = smbus2.SMBus(bus_number)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_tsl2561(bus):
    """Initializes the TSL2561 sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(bus, address=TSL2561_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

