    """Reads the illuminance from the sensor."""
    try:
        lux = sensor.lux
        return lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def validate_light_level(lux):
    """Validates the light level reading."""
    if lux is None:
        return False
    if not 0 <= lux <= 10000:  # TSL2561 datasheet specifies range
