# temperature monitoring of a DS18B20 over 1-Wire on a Raspberry Pi
# Reads the temperature once and reports it to standard output
import time
import w1thermsensor


def read_temperature(sensor_type="ds18b20"):
    """Read the temperature from a 1-Wire sensor and return it in Celsius."""
    # Create a 1-Wire sensor object for the DS18B20 default
    try:
        temperature_sensor = w1thermsensor.W1ThermSensor(sensor_type)
    except w1thermsensor.errors.NoSensorFoundError:
        # The sensor is not present on the 1-Wire bus
        return None
    try:
        # Pull the current temperature from the sensor
        measured_temperature = temperature_sensor.get_temperature()
        return round(measured_temperature, 2)
    except Exception:
        # An unexpected error occurred while reading the sensor
        return None


def main():
    """Read the temperature and report it to the console."""
    # Read the temperature from the 1-Wire sensor
    current_temperature = read_temperature()
    if current_temperature is not None:
        # Print the temperature so the monitoring tool can consume it
        print("Measured temperature: {0} C".format(current_temperature))
    else:
        # The sensor was not found or an error occurred
        print("Could not read temperature from the sensor")
    # Mark the script as finished so the monitoring loop can continue
    print("Temperature monitoring cycle complete")


if __name__ == "__main__":
    try:
        # Execute the temperature monitoring routine
        main()
    except KeyboardInterrupt:
        # The operator interrupted the script
        print("Script interrupted by operator")
    finally:
        # Release any resources held by the 1-Wire library
        w1thermsensor.W1ThermSensor.cleanup()
        print("1-Wire resources released")

