"""
Reads temperature and humidity from a DHT22 sensor connected to a Raspberry Pi.
"""

import time
import board
import adafruit_dht

# Configuration
DHT_PIN = board.D4  # GPIO pin connected to the DHT22 data pin
READ_INTERVAL_SECONDS = 5

def initialize_sensor():
    """Initializes the DHT22 sensor."""
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN)
        return dht_device
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        temperature_c = sensor.temperature
        humidity = sensor.humidity
        return temperature_c, humidity
    except RuntimeError as e:
        print(f"DHT22 sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading DHT22 sensor: {e}")
        return None, None

def validate_data(temperature_c, humidity):
    """Validates temperature and humidity readings."""
    if temperature_c is not None and (temperature_c < -40 or temperature_c > 80):
        print("Warning: Temperature out of range.")
    if humidity is not None and (humidity < 0 or humidity > 100):
        print("Warning: Humidity out of range.")
    return temperature_c, humidity

def report_state(temperature_c, humidity):
    """Reports the temperature and humidity to standard output."""
    if temperature_c is not None and humidity is not None:
        print(f"Temperature: {temperature_c:.1f} °C")
        print(f"Humidity: {humidity:.1f} %")
    else:
        print("Failed to read temperature and humidity.")

def main():
    """Main function to read and report DHT22 sensor data."""
    sensor = initialize_sensor()

    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return

    try:
        while True:
            temperature_c, humidity = read_sensor_data(sensor)

            if temperature_c is not None and humidity is not None:
                temperature_c, humidity = validate_data(temperature_c, humidity)
                report_state(temperature_c, humidity)

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        sensor.exit()  # Release resources

if __name__ == "__main__":
    main()

