#!/usr/bin/env python3
# pwm_profile_demo.py
# Demonstrates PWM output on six GPIO pins using gpiozero.
# Profiles each pin and reports the state to the console.

import time
import gpiozero
import logging

# Configure logging for debugging and error reporting
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the GPIO pins to use (BCM numbering)
PIN_CONFIG = [
    {'pin_num': 12, 'init_state': False},
    {'pin_num': 13, 'init_state': True},
    {'pin_num': 18, 'init_state': True},
    {'pin_num': 19, 'init_state': False},
    {'pin_num': 22, 'init_state': True},
    {'pin_num': 23, 'init_state': False}
]

def initialize_pins(pin_config):
    """Initializes the GPIO pins with PWM and sets the initial state."""
    pwm_outputs = []
    for pin_config in pin_config:
        try:
            pwm = gpiozero.PWMOutputDevice(pin_config['pin_num'], frequency=100, initial_value=pin_config['init_state'])
            pwm_outputs.append(pwm)
            logging.info(f"Pin {pin_config['pin_num']} initialized with state {pin_config['init_state']}")
        except Exception as e:
            logging.error(f"Failed to initialize pin {pin_config['pin_num']}: {e}")
            return None
    return pwm_outputs

def profile_pins(pwm_outputs):
    """Profiles each PWM output and reports the state."""
    if not pwm_outputs:
        logging.error("No PWM outputs initialized. Exiting.")
        return

    try:
        for pwm in pwm_outputs:
            pwm.value = not pwm.value  # Toggle the state
            logging.info(f"Pin {pwm.pin_num} set to: {pwm.value}")
        time.sleep(2)  # Wait for 2 seconds
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred during profiling: {e}")
    finally:
        cleanup_pins(pwm_outputs)

def cleanup_pins(pwm_outputs):
    """Releases the GPIO pins."""
    for pwm in pwm_outputs:
        pwm.close()
        logging.info(f"Pin {pwm.pin_num} released.")

if __name__ == "__main__":
    pwm_outputs = initialize_pins(PIN_CONFIG)
    if pwm_outputs:
        profile_pins(pwm_outputs)

