# serial monitor for a Raspberry Pi device using pyserial
# Reads data from a connected device over the serial port and prints it
# to standard output.
import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT_SECONDS = 0.5


def open_serial_port(port_path, baud_value, timeout_seconds):
    """Open and configure the serial port for the connected device."""
    # Create and return a serial port object
    return serial.Serial(port_path, baud_value, timeout=timeout_seconds)


def read_serial_line(serial_connection):
    """Read one line of data from the serial port."""
    # Strip whitespace and return the decoded line
    return serial_connection.readline().decode("ascii", errors="replace").strip()


def process_reading(reading_text):
    """Print the reading if it is valid."""
    # Reject an empty or null reading
    if reading_text:
        print("Reading:", reading_text)


def main():
    """Continuously read and process serial data until interrupted."""
    serial_connection = None
    try:
        # Open the serial port to the connected device
        serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT_SECONDS)
        while True:
            reading_text = read_serial_line(serial_connection)
            process_reading(reading_text)
            time.sleep(0.05)
    except KeyboardInterrupt:
        # Allow the user to stop the monitor cleanly
        print("Stopping serial monitor")
    except serial.SerialException as error_info:
        # Report a serial port error
        print("Serial error:", error_info)
    finally:
        # Always release the serial port resource
        if serial_connection is not None:
            serial_connection.close()


if __name__ == "__main__":
    main()

