#!/usr/bin/env python3

import time
import sys
from gpiozero import PWMOutputDevice

# Pin assignments (BCM numbering)
PINS = [4, 12, 23, 24, 25, 27]

def apply_states(devices):
    """Apply a list of PWM values to the output devices."""
    try:
        for pin, value in zip(devices.pins, devices.values):
            # Use a try-except block to handle potential errors
            try:
                devices.set_value(pin, value)
            except Exception as e:
                print(f"Error setting pin {pin}: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Error applying states: {e}", file=sys.stderr)


def main():
    """Main program loop."""
    try:
        # Initialize PWM devices on the specified pins
        devices = [PWMOutputDevice(pin) for pin in PINS]

        while True:
            # Set the PWM values (these are lists of values, one for each device)
            values = [0.0] * len(devices)

            # Apply the values to the devices
            apply_states(devices)

            # Print the current time
            print(f"{time.time():.2f}")

            # Wait for 2 seconds
            time.sleep(2)

    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        print("\nExiting...")
    except Exception as e:
        # Catch any other exceptions
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        # Ensure the devices are stopped and pins are released
        for device in devices:
            device.close()
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Control a PCA9685 PWM servo driver on a Raspberry Pi using gpiozero.

This script applies a sequence of state values to the 16 servo channels
supported by the PCA9685 and reports the actual state set to standard output.
"""

import time
import logging
from gpiozero import PWMOutputDevice

# Logging documents the servo control activity.
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Servo channel assignments for the PCA9685.
SERVO_CHANNELS = 16


def create_servo_devices():
    """Create gpiozero PWMOutputDevice objects for each servo channel."""
    # One device per channel allows independent control.
    servo_devices = []
    for channel_index in range(SERVO_CHANNELS):
        # Map channel index to gpio pin (BCM numbering).
        gpio_pin = 2 + channel_index * 2
        try:
            servo_devices.append(PWMOutputDevice(gpio_pin))
        except Exception as device_error:
            # A missing or inactive device returns a ValueError.
            if isinstance(device_error, ValueError):
                logging.warning("Servo device missing on pin %d", gpio_pin)
            else:
                logging.error("Servo device error: %s", device_error)
            servo_devices.append(None)
    return servo_devices


def set_servo_state(servo_devices, state_value):
    """Apply a state value to every servo channel held by devices."""
    # Each device accepts a single floating-point duty value.
    for device in servo_devices:
        if device is not None:
            try:
                device.value = state_value
            except Exception as set_error:
                logging.error("Servo set error on pin %d: %s", device.pin, set_error)


def validate_state(state_value):
    """Check a state value is within the valid duty range."""
    # The PCA9685 expects values between 0 and 127.
    if not 0 <= state_value <= 127:
        raise ValueError("Servo state must be between 0 and 127")
    return True


def main():
    """Run a single pass of servo state control and report results."""
    servo_devices = create_servo_devices()
    try:
        # Set every channel to the mid-point duty value.
        set_servo_state(servo_devices, 64.0)
        time.sleep(0.5)
        logging.info("Servos set to state 64.0")
    except Exception as control_error:
        # Report any failure during the control pass.
        logging.error("Servo control failed: %s", control_error)
    finally:
        # Release all servo devices held by gpiozero.
        for device in servo_devices:
            if device is not None:
                device.close()


if __name__ == "__main__":
    main()

